package Common;

//玩家信息
message UserInfo
{
	optional int32 seatId = 1;//座位号
	optional int64 userId = 2;//userId
	optional int32 isReady = 3;//是否准备(0，1)
	optional int32 isAi = 4;//是否托管(0，1)
	optional int32 isOnline = 5;//是否在线(0，1)
	optional int64 money = 6;//钱
	optional int64 turnMoney = 7;//玩家金币变化
	optional string strUserInfo = 8;
	repeated int32 cards = 9;
	optional int32 cardCount = 10[default=0];
	optional int32 rank = 11;
	repeated int32 identity = 12;//大部分游戏结算还是用到了身份信息

	extensions 100 to 1000;
}

//房间信息
message RoomInfo
{
	optional int32 level = 1;//房间等级
	optional int32 baseChip = 2;//底注
	optional int32 totalGame = 3;//游戏局数
	extensions 100 to 1000;
}

//C2S:用户所取消的操作码
message UserCancel
{
	optional int64 code = 1;//操作码
}

//Lua报错
message LuaError {
	optional int32 errCode = 1;
	optional string msg = 2;
	extensions 100 to 1000;
}

message TimerInfo {
	optional int64 uid = 1; // userid
	optional int64 uniqueId = 2;// 定时器ID
	optional int32 time = 3; // 剩余时间
	extensions 100 to 1000;
}

//登陆信息
message LoginInfo {
	optional RoomInfo roomInfo = 1;
	optional UserInfo user = 2;
	repeated UserInfo others = 3;
	repeated SyncData syncData = 4;
	optional ProcessInfo processInfo = 5;
	optional bool isReconnect = 6[default=false];
	repeated TimerInfo timerList = 7;
	extensions 100 to 1000;
}

message ProcessInfo {
	optional int32 startTime = 1;
}

message GameMessage {
	optional int64 header = 1;
	optional string body = 2;
}

//数据变化
message SyncData {
	optional string field = 1;
	optional string data = 2;
	optional int32 uid = 3;
}

//选择手牌
message SelCardInfo {
	optional int64 uid = 1;
	optional int32 number = 2;
	optional int32 time = 3;
	extensions 100 to 1000;
}

//通用操作信息
message GeneralOpInfo {
	optional int64 uid = 1;
	repeated GeneralOpUnit opInfo = 2;
	optional int32 time = 3;
	extensions 100 to 1000;
}

//单元操作信息
message GeneralOpUnit {
	optional int32 opCode = 1;
	repeated int32 opData = 2;
	extensions 100 to 1000;
}

//多玩家操作信息
message MultipleOpUser {
	repeated GeneralOpInfo opUsers = 1;
	extensions 100 to 1000;
}

// 主花色信息
message ZhuHuaSeInfo{
	optional int32 zhuHuaSe = 1;
	extensions 100 to 1000;
}

//操作结果
message GeneralOpResult {
	optional int64 uid = 1;
	optional int32 opCode = 2;
	repeated int32 opData = 3;
	optional int32 errCode = 4;
	optional int32 opCardType = 5;
	optional int64 maxUid = 6;
	optional int32 totalGame = 7; //判斷是否是首局
	extensions 100 to 1000;
}

//发牌信息
message DealCardInfo {
	repeated UserCardInfo dealCards = 1;
	optional int32 firstCard = 2;
	optional int32 firstShowCardByte = 3;
	optional int64 firstShowCardFirstUid = 4;
	optional int64 firstShowCardSecondUid = 5;
	extensions 100 to 1000;
}

//玩家手牌信息
message UserCardInfo {
	optional int64 uid = 1;
	optional int32 count = 2; //其他玩家只广播手牌数量
	repeated int32 cards = 3; //当前玩家广播牌值
	optional int32 seatId = 4;
	extensions 100 to 1000;
}

message GameStart {	
	optional int32 totalGame = 1;
	extensions 100 to 1000;
}

//用户游戏结果信息
message UserResult
{
	optional int64 uid = 1;
	optional int32 seatId = 2;
	optional int32 money = 3;
	optional int32 turnMoney = 4;
	optional int32 exp = 5;
	optional int32 rank = 6;
	repeated int32 leftCards = 7;//剩下的手牌
	
	//extend Common.UserResult {
	optional int32 bombScore = 8;
	optional int32 totalScore = 9;
	optional int32 winType = 10;
	optional int32 gameType = 11; // 游戏类型1v3,2v2,3v1
	repeated int32 friends = 12; //队友列表
	repeated int32 leftJokerCards = 13; //被关的牌
	optional int32 penaltyInfo = 14; //托管惩罚标记
	//}
	extensions 100 to 1000;
}

//游戏结果信息，包含所有用户结果信息
message GameResult {
	repeated UserResult results = 1;
	//extend Common.GameResult {
	optional int32 cardCaller 	= 2; 	//亮牌者uid
	repeated int32 cards 		= 3; 		//亮的牌
	//}
	extensions 100 to 1000;
}

//玩家进牌信息
message PayCardInfo {
	optional int64 fromUid = 1;
	optional int64 toUid = 2;
	repeated int32 cards = 3;
}

//阵营抓分情况
message CampScoreInfo{
	optional string kouDiType = 1; // 扣底类型
	optional int32 totalScore = 2; //总共得到的分数
	optional int32 curScore = 3; //当前一圈得到的分数
	extensions 100 to 1000;
}

message BlankMsg {
	
}

message ExchangeCardInfo {
	optional int64 uid1 = 1;
	optional int64 uid2 = 2;
	repeated int32 cards1 = 3;
	repeated int32 cards2 = 4;
	extensions 100 to 1000;
}

//打牌开始
message PlayCardStart {
	optional int64 uid 				= 1; //玩家id
	optional bool isNew 			= 2; //是否新的一回合
	optional int32 time 			= 3; //时间
	repeated int32 banCards 		= 4; //不能打出的排列表
	optional bool isAutoPlay		= 5; //是否是最后一手牌自动打出
	optional int32 recordLen        = 6;//总的出牌记录长度
	extensions 100 to 1000;
}

//打牌结果
message PlayCardResult {
	optional int64 uid 		= 1;
	optional int32 opCode 	= 2; //出，不出选择
	repeated int32 opData 	= 3; //出牌列表
	optional int32 cardType = 4; //牌型
	optional int32 cardByte = 5; //牌型基准牌值
	optional int32 errCode 	= 6;
	optional int32 maxUid 	= 7;
	optional int32 leftTime = 8; // 打牌出错时剩余时间
	repeated int32 handCards = 9;//用于同步手牌信息
	optional bool isTimeOut = 10;//客户端玩家要不起时超时操作
	repeated int32 banCards = 11;//不能打出的排列表
	optional bool isNew = 12;//是否是首出
	optional int32 recordLen = 13;//总的出牌记录长度
	extensions 100 to 1000;
}

// 用户倍数变化
message UserBeiShuInfo {
	message BeiShuUnit {
		optional int64 uid = 1;
		optional int32 oldBeishu = 2;
		optional int32 newBeishu = 3;
		optional string opStr = 4;
	}
	repeated BeiShuUnit beiShuInfo = 1;
	optional string anims = 4;
}

//用户钱币变化
message UserMoneyInfo {
	message MoneyUnit {
		optional int64 uid = 1;
		optional int32 changedMoney = 2;
	}
	repeated MoneyUnit moneyInfo = 1;
}


//玩家身份变化
message identityInfo {
	optional int32 userId = 1;
	repeated int32 identity = 2;//大部分游戏结算还是用到了身份信息
	optional string anims = 3; //交互ID
	extensions 100 to 1000;
}

//玩家排名变化
message rankInfo {
	optional int32 userId = 1;
	optional int32 rank = 2;
	optional string anims = 3; //交互ID
	extensions 100 to 1000;
}

//扣底类型
message KouDiInfo {
	optional int32 koudiType = 1;//闲家扣底类型     1为庄家保底，2-5为闲家扣底，分别为单扣，双扣，姐妹扣，公孙扣
	optional int32 gydf = 2;//勾下来、幺下来、带帽、反带帽动画
	repeated int32 cards = 3; // 底牌
}

//同步数据
message syncData {
	optional string field = 1;
	optional string data = 2;
	optional int64 uid = 3;
}

message SpecialCardsInfo {
	message SpecialCardsUnit {
		optional int32 uid = 1;
		repeated int32 cards = 2;
	}
	repeated SpecialCardsUnit info = 1;
	optional string anims = 2; //交互ID
}

message UserCanLiangInfo {
	optional int32 seatId = 1;
	optional int64 uid = 2;
	repeated int32 cards =3;
	optional int32 time = 4;

}

message LiangPaiUnit {
	optional int64 uid = 1;
	optional int32 opCode = 2;
	repeated int32 opData = 3; //玩家展示亮的牌列表
}

message UserLiangPaiResult {
	optional LiangPaiUnit lightCardUser = 1; //选择亮牌的玩家
	repeated LiangPaiUnit followers = 2;	//被动跟亮牌的玩家
	optional int32 leftTime = 3;//剩余时间
}



message SettleData {
	optional string settleData = 1;
}

message BaseChipTimes {
	optional int32 times = 1; //底注倍数
}

message UserScore {
	optional int32 uid = 1;
	optional int32 score = 2;
}

message ScoreData {
	repeated UserScore scoreData = 1;
}

//叫分选项
message JiaoFenInfo {
	repeated int32 choice = 1;//可选项
	optional int32 curScore =2;//当前已选分数
	optional int32 leftTime = 3;//定时器剩余时间
	optional int32 curUid = 4;//当前轮到的玩家的uid
	optional int32 uid    = 5;//发送给对应玩家的uid
}

//叫分结果
message JiaoFenResult {
	optional int32 result = 1;//叫分结果
	optional int32 opCode = 2;//操作码
	optional int32 uid 	  = 3;
	repeated int32 holeCard = 4;//底牌信息
	optional int32 multipleNumber = 5;//倍数信息
	optional int32 bankerId = 6;//庄家id
}

//玩家将底牌收入信息
message holeCardInfo {
	repeated int32 holeCard = 1;//底牌信息
	optional int64 addCardsUid = 2;//收入底牌玩家的id
}

message RengpaiData {
	optional int64 uid = 1;
	optional int32 time = 2; //扔牌时间
	repeated int32 opData = 3; //可以扔的牌
}

message RengpaiResult {
	optional int64 uid = 1;
	optional int32 leftTime = 2; //扔牌时间
	repeated int32 opData = 3; //可以扔的牌
	optional int32 opCode = 4;
	optional bool  isShow = 5;
}


//贡开始
message TributeStart {
	repeated int64 uid 				= 1; //玩家id列表
	repeated int32 opData 			= 2; //贡牌
	optional int32 time 			= 3; //时间
	extensions 100 to 1000;
}

//贡信息列表
message TributeSelectedUnit {
	optional int32 uid = 1;
	optional int32 index = 2;
	optional int32 byte = 3;
	optional int32 selectBackCard = 4;
}

//贡信息结果列表
message TributeSelectedData {
	repeated TributeSelectedUnit selectedData = 1;
}

// 好牌测试信息
message GoodCardTestInfo {
	optional int32 times = 1; //前端提交测试局数
	optional string result = 2;//后端计算结果,通过Json传到客户端
}

// 叫地主阶段通用操作广播协议
message FixLandLordOpInfo  {
	repeated FixLandLordOpUnit choice = 1;
	optional int32 time = 2;
	optional int64 curUid = 3; //当前操作的玩家的uid
	optional int64 uid = 4; //接收消息玩家的uid
	optional int32 opCode = 5;
	optional int64 lastUid = 6;//最后操作玩家的uid
	optional int32 daoCount = 7;// 倒牌次数（针对前端会做对应操作）
}

message FixLandLordOpUnit  {
	optional int32 opCode = 1;
	optional int32 times = 2;// --本局进行了多少次本操作，用于前端同opCode不同显示
}

message GameBreakUserInfoUnit {
	optional int32 uid = 1;
	optional string nickName = 2;
	optional int32 money = 3;
	optional int32 moneyAfter = 4;
}

message GameBreakInfo {
	repeated GameBreakUserInfoUnit userInfo = 1;
}
message ClientChangeEvent {
	optional string event = 1;
}

message DirectGameOverInfo {
	message UserHandCardsInfo {
		optional int32 uid = 1;
		repeated int32 cards = 2;
		optional bool isSpecialSettle = 3;
		repeated int32 liangOpData = 4;//特殊牌列表
	}

	optional int32 uid 		= 1; //玩家id
	repeated UserHandCardsInfo handCardInfo = 2;//手牌信息

}

message YaoCardInfo {
	optional int32 uid 		= 1; //玩家id
	optional int32 opCode 	= 2; //操作码
	repeated int32 opData 	= 3; //要牌列表
	optional int32 time 	= 4;
	optional int32 index 	= 5; 
}

// 玩家手牌数据
message SyncUserHandCards {
	optional int32 uid 		 = 1;
	repeated int32 handCards = 2;
}

//玩家换牌数据
message ChangCardInfo {
	optional int32 uid = 1; //接收消息玩家的uid
	optional int32 curUid = 2; //当前操作玩家的uid
	repeated int32 tipCards 	= 3; //可以提起的牌
	optional int32 num = 4; //可以提起牌最多的数量
	optional int32 time = 5 ;//剩余时间
	repeated int32 changeCards 	= 6; //更换回来的牌
	repeated int32 throwCards 	= 7; //从手中换出去的牌
	optional int32 opCode = 8; //操作码
	repeated int32 opData 	= 9; //提交可操作的牌
	optional int32 cardType = 10; //牌型
	optional int32 cardByte = 11; //牌型基准牌值

}
//公共前置操作按钮数据
message CommonOpInfo {
	optional int32 uid = 1;
	repeated int32 cards = 2; // 明牌操作时对应的cards
	repeated FixLandLordOpUnit choice = 3;// --玩家可选操作
	optional int32 time = 4;
	optional int32 opCode = 5;//前端提交数据里的opCode
	optional int32 times = 6;//result返回对应opCode已被操作的次数

}
//流程开始时流程名数据
message StartStageInfo {
	optional string stage =1;
}
//可选牌
message OpecialCards {
	repeated int32 cards = 1;
	optional int32 min = 2;
	optional int32 max = 3;
}
//限制条件
message TriLimitItem {
	optional int32 count = 1;//选牌张数
    optional int32 min = 2;//最少选牌张数
    optional int32 max = 3;//最多选牌张数
    repeated int32 needCards = 4;//必须选的牌
    repeated int32 limitCards = 5;//不能选的牌
    optional OpecialCards optionalCards = 6;//可选牌
}
//预选条件
message PreInfo {
	optional int32 uid = 1;
	repeated int32 cards = 2;
}
//进贡信息
message TributeInfo {
	optional int32 uid = 1;
	optional int32 opCode = 2;
	repeated int32 cards = 3; // 总的cards
	repeated int32 selectCards = 4; // 选择的cards
	optional TriLimitItem limit = 5;//限制条件
	repeated PreInfo preInfo = 6;//预选条件
	repeated int32 toUids = 7;//给哪些玩家
	optional int32 time = 8;
	optional int32 state = 9;//当前属于进贡的哪个流程
	repeated int32 handCards = 10;//操作后的手牌
	optional int32 count = 11;//手牌数量
	optional int32 left = 12;//剩余操作玩家数量
	optional int32 errCode = 13;
}
//进贡等待信息
message TributeWaitInfo {
	optional int32 uid = 1;
	optional int32 time = 2;
	optional int32 leftCount = 3;//剩余提交操作玩家数量
	optional int32 opCode = 4;
	optional int32 state = 5;//当前属于进贡的哪个流程
	repeated int32 toUids = 6;//给哪些玩家
}

message TributeRetAndChoiceInfo {
	optional int32 uid = 1;
	optional int32 from = 2;
	optional int32 opCode = 3;
	repeated int32 cards = 4; // 总的cards
	optional int32 state = 5;//当前属于进贡的哪个流程
}

//亮牌（新）数据结构
message LiangPaiMsg  {
	repeated int64 opUsersId = 1; //当前操作玩家的uid表
	optional int64 uid = 2; //执行操作玩家的uid
	optional LiangPaiInfo liangPaiInfo = 3;//亮牌玩家相关数据结构
	optional int32 opCode = 4;//前端提交操作的opCode
	repeated int32 opData = 5;//前端提交操作的opData
	optional int32 time  = 6;
	optional int32 isLastOperator = 7; // 是否是最后一个操作者
	optional int32 operatorNum = 8; // 第几个操作者
}

//亮牌玩家相关数据结构
message LiangPaiInfo  {
	repeated int32 opData = 1;//手牌中可操作牌信息
	optional int32 maxCount = 2;//最多可选牌的张数
	optional int32 minCount = 3;//最少可选牌的张数
	repeated FixLandLordOpUnit choice = 4;//可选操作
	repeated int32 mustChoseOpData = 5;//必选牌，必须选择其中minCount数量的牌数
	repeated FixLandLordOpUnit associateOp = 6;//关联操作,必须满足mustChoseOpData所描述的情况才可选其中的操作
	optional int64 uid = 7;//亮牌玩家的uid
}

message ChoiceDataUnit {
	repeated int32 bytes = 1;
}

message PlayerChoiceInfo  {
	repeated int32 opData = 1;//操作信息
	repeated ChoiceDataUnit choiceData = 2;//可以操作的牌型的信息
	optional int32 uid = 3;//操作牌玩家的uid
	optional int32 time  = 4;
}
